import{_ as a,a0 as d,w as r,s as p,ao as i,I as e,x as t,a1 as o,A as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const h=JSON.parse('{"title":"如何更改 Linux 控制台上的字体 | LCTT x X-CMD","titleTemplate":false,"description":"如何更改 Linux 控制台上的字体 | LCTT (201802) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何更改 Linux 控制台上的字体 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何更改 Linux 控制台上的字体 | LCTT (201802) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201802/20180104 How to Change Your Linux Console Fonts","title":"如何更改 Linux 控制台上的字体","tag":"201802","desc":""},"relativePath":"201802/20180104 How to Change Your Linux Console Fonts.md","filePath":"[post].md"}'),u={name:"201802/20180104 How to Change Your Linux Console Fonts.md"};function f(b,s,g,x,m,k){const n=d("Link");return r(),p("div",null,[s[43]||(s[43]=i('<h1 id="如何更改-linux-控制台上的字体" tabindex="-1">如何更改 Linux 控制台上的字体 <a class="header-anchor" href="#如何更改-linux-控制台上的字体" aria-label="Permalink to “如何更改 Linux 控制台上的字体”">​</a></h1><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/font-size_0.png?itok=d97vmyYa" alt=""></p><p>我尝试尽可能的保持心灵祥和，然而总有一些事情让我意难平，比如控制台字体太小了。记住我的话，朋友，有一天你的眼睛会退化，无法再看清你编码时用的那些细小字体，到那时你就后悔莫及了。</p><p>幸好，Linux 死忠们，你可以更改控制台的字体。按照 Linux 一贯的尿性，不断变化的 Linux 环境使得这个问题变得不太简单明了，而 Linux 上也没有字体管理这么个东西，这使得我们很容易就被搞晕了。本文，我将会向你展示，我找到的更改字体的最简方法。</p><h3 id="linux-控制台是个什么鬼" tabindex="-1">Linux 控制台是个什么鬼？ <a class="header-anchor" href="#linux-控制台是个什么鬼" aria-label="Permalink to “Linux 控制台是个什么鬼？”">​</a></h3><p>首先让我们来澄清一下我们说的到底是个什么东西。当我提到 Linux 控制台，我指的是 TTY1-6，即你从图形环境用 <code>Ctrl-Alt-F1</code> 到 <code>F6</code> 切换到的虚拟终端。按下 <code>Ctrl+Alt+F7</code> 会切回图形环境。(不过这些热键已经不再通用，你的 Linux 发行版可能有不同的键映射。你的 TTY 的数量也可能不同，你图形环境会话也可能不在 <code>F7</code>。比如，Fedora 的默认图形会话是 <code>F2</code>，它只有一个额外的终端在 <code>F1</code>。) 我觉得能同时拥有 X 会话和终端会话实在是太酷了。</p><p>Linux 控制台是内核的一部分，而且并不运行在 X 会话中。它和你在没有图形环境的<ruby>无头<rt>headless</rt></ruby>服务器中用的控制台是一样的。我称呼在图形会话中的 X 终端为终端，而将控制台和 X 终端统称为终端模拟器。</p>',7)),e("p",null,[s[1]||(s[1]=t("但这还没完。Linux 终端从早期的 ANSI 时代开始已经经历了长久的发展，多亏了 Linux framebuffer，它现在支持 Unicode 并且对图形也有了有限的一些支持。而且出现了很多在控制台下运行的",-1)),o(n,{href:"https://linux.cn/article-9320-1.html"},{default:l(()=>[...s[0]||(s[0]=[t("多媒体应用",-1)])]),_:1}),s[2]||(s[2]=t("，这些我们在以后的文章中会提到。",-1))]),s[44]||(s[44]=e("h3",{id:"控制台截屏",tabindex:"-1"},[t("控制台截屏 "),e("a",{class:"header-anchor",href:"#控制台截屏","aria-label":"Permalink to “控制台截屏”"},"​")],-1)),e("p",null,[s[5]||(s[5]=t("获取控制台截屏的最简单方法是让控制台跑在虚拟机内部。然后你可以在宿主系统上使用中意的截屏软件来抓取。不过借助 ",-1)),o(n,{href:"http://jwilk.net/software/fbcat"},{default:l(()=>[...s[3]||(s[3]=[t("fbcat",-1)])]),_:1}),s[6]||(s[6]=t(" 和 ",-1)),o(n,{href:"https://github.com/jwilk/fbcat/blob/master/fbgrab"},{default:l(()=>[...s[4]||(s[4]=[t("fbgrab",-1)])]),_:1}),s[7]||(s[7]=t(" 你也可以直接在控制台上截屏。",-1)),s[8]||(s[8]=e("code",null,"fbcat",-1)),s[9]||(s[9]=t(" 会创建一个可移植的像素映射格式（PPM）的图像； 这是一个高度可移植的未压缩图像格式，可以在所有的操作系统上读取，当然你也可以把它转换成任何喜欢的其他格式。",-1)),s[10]||(s[10]=e("code",null,"fbgrab",-1)),s[11]||(s[11]=t(" 则是 ",-1)),s[12]||(s[12]=e("code",null,"fbcat",-1)),s[13]||(s[13]=t(" 的一个封装脚本，用来生成一个 PNG 文件。很多人写过多个版本的 ",-1)),s[14]||(s[14]=e("code",null,"fbgrab",-1)),s[15]||(s[15]=t("。每个版本的选项都有限而且只能创建截取全屏。",-1))]),s[45]||(s[45]=i('<p><code>fbcat</code> 的执行需要 root 权限，而且它的输出需要重定向到文件中。你无需指定文件扩展名，只需要输入文件名就行了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo fbcat &gt; Pictures/myfile</span></span></code></pre></div><p>在 GIMP 中裁剪后，就得到了图 1。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/fig-1_10.png" alt=""></p><p><em>图 1 ： 裁剪后查看</em></p><p>如果能在左边空白处有一点填充就好了，如果有读者知道如何实现请在留言框中告诉我。</p><p><code>fbgrab</code> 还有一些选项，你可以通过 <code>man fbgrab</code> 来查看，这些选项包括对另一个控制台进行截屏，以及延时截屏等。在下面的例子中可以看到，<code>fbgrab</code> 截屏跟 <code>fbcat</code> 截屏类似，只是你无需明确进行输出重定性了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo fbgrab Pictures/myOtherfile</span></span></code></pre></div><h3 id="查找字体" tabindex="-1">查找字体 <a class="header-anchor" href="#查找字体" aria-label="Permalink to “查找字体”">​</a></h3><p>就我所知，除了查看字体存储目录 <code>/usr/share/consolefonts/</code>（Debian 等），<code>/lib/kbd/consolefonts/</code> （Fedora），<code>/usr/share/kbd/consolefonts</code> （openSUSE）外没有其他方法可以列出已安装的字体了。</p><h3 id="更改字体" tabindex="-1">更改字体 <a class="header-anchor" href="#更改字体" aria-label="Permalink to “更改字体”">​</a></h3><p>可读字体不是什么新概念。我们应该尊重以前的经验！可读性是很重要的。可配置性也很重要，然而现如今却不怎么看重了。</p>',12)),e("p",null,[s[17]||(s[17]=t("在 Debian/Ubuntu 等系统上，可以运行 ",-1)),s[18]||(s[18]=e("code",null,"sudo dpkg-reconfigure console-setup",-1)),s[19]||(s[19]=t(" 来设置控制台字体，然后在控制台运行 ",-1)),s[20]||(s[20]=e("code",null,"setupcon",-1)),s[21]||(s[21]=t(" 命令来让变更生效。",-1)),s[22]||(s[22]=e("code",null,"setupcon",-1)),s[23]||(s[23]=t(" 属于 ",-1)),s[24]||(s[24]=e("code",null,"console-setup",-1)),s[25]||(s[25]=t(" 软件包中的一部分。若你的 Linux 发行版中不包含该工具，可以在 ",-1)),o(n,{href:"https://software.opensuse.org/package/console-setup"},{default:l(()=>[...s[16]||(s[16]=[t("openSUSE",-1)])]),_:1}),s[26]||(s[26]=t(" 中下载到它。",-1))]),s[46]||(s[46]=i(`<p>你也可以直接编辑 <code>/etc/default/console-setup</code> 文件。下面这个例子中设置字体为 32 点大小的 Terminus Bold 字体，这是我的最爱，并且严格限制控制台宽度为 80 列。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ACTIVE_CONSOLES=&quot;/dev/tty[1-6]&quot;</span></span>
<span class="line"><span>CHARMAP=&quot;UTF-8&quot;</span></span>
<span class="line"><span>CODESET=&quot;guess&quot;</span></span>
<span class="line"><span>FONTFACE=&quot;TerminusBold&quot;</span></span>
<span class="line"><span>FONTSIZE=&quot;16x32&quot;</span></span>
<span class="line"><span>SCREEN_WIDTH=&quot;80&quot;</span></span></code></pre></div><p>这里的 <code>FONTFACE</code> 和 <code>FONTSIZE</code> 的值来自于字体的文件名 <code>TerminusBold32x16.psf.gz</code>。是的，你需要反转 <code>FONTSIZE</code> 中值的顺序。计算机就是这么搞笑。然后再运行 <code>setupcon</code> 来让新配置生效。可以使用 <code>showconsolefont</code> 来查看当前所用字体的所有字符集。要查看完整的选项说明请参考 <code>man console-setup</code>。</p><h3 id="systemd" tabindex="-1">Systemd <a class="header-anchor" href="#systemd" aria-label="Permalink to “Systemd”">​</a></h3><p>Systemd 与 <code>console-setup</code> 不太一样，除了字体之外，你无需安装任何东西。你只需要编辑 <code>/etc/vconsole.conf</code> 然后重启就行了。我在 Fedora 和 openSUSE 系统中安装了一些额外的大字号的 Terminus 字体包，因为默认安装的字体最大只有 16 点而我想要的是 32 点。然后将 <code>/etc/vconsole.conf</code> 的内容修改为：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>KEYMAP=&quot;us&quot;</span></span>
<span class="line"><span>FONT=&quot;ter-v32b&quot;</span></span></code></pre></div>`,6)),e("p",null,[s[28]||(s[28]=t("下周我们还将学习一些更加酷的控制台小技巧，以及一些在控制台上运行的",-1)),o(n,{href:"https://linux.cn/article-9320-1.html"},{default:l(()=>[...s[27]||(s[27]=[t("多媒体应用",-1)])]),_:1}),s[29]||(s[29]=t("。",-1))]),s[47]||(s[47]=e("hr",null,null,-1)),e("p",null,[s[31]||(s[31]=t("via: ",-1)),o(n,{href:"https://www.linux.com/learn/intro-to-linux/2018/1/how-change-your-linux-console-fonts"},{default:l(()=>[...s[30]||(s[30]=[t("https://www.linux.com/learn/intro-to-linux/2018/1/how-change-your-linux-console-fonts",-1)])]),_:1})]),e("p",null,[s[35]||(s[35]=t("作者：",-1)),o(n,{href:"https://www.linux.com/users/cschroder"},{default:l(()=>[...s[32]||(s[32]=[t("Carla Schroder",-1)])]),_:1}),s[36]||(s[36]=t(" 译者：",-1)),o(n,{href:"https://github.com/lujun9972"},{default:l(()=>[...s[33]||(s[33]=[t("lujun9972",-1)])]),_:1}),s[37]||(s[37]=t(" 校对：",-1)),o(n,{href:"https://github.com/wxy"},{default:l(()=>[...s[34]||(s[34]=[t("wxy",-1)])]),_:1})]),e("p",null,[s[40]||(s[40]=t("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[38]||(s[38]=[t("LCTT",-1)])]),_:1}),s[41]||(s[41]=t(" 原创编译，",-1)),o(n,{href:"https://linux.cn/"},{default:l(()=>[...s[39]||(s[39]=[t("Linux中国",-1)])]),_:1}),s[42]||(s[42]=t(" 荣誉推出",-1))])])}const L=a(u,[["render",f]]);export{h as __pageData,L as default};
